DELETE FROM `form_manager`;
INSERT INTO `form_manager` (`id`, `slug`, `table_name`, `title`, `description`, `roles`, `react_route`, `submit_endpoint`, `http_method`, `status`, `version`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(1, 'form-constructor', 'form_manager', 'Construtor de Formulários', 'Meta-formulário: cada grupo abaixo define os campos de uma das quatro tabelas do módulo Form. Preencha de cima para baixo — o formulário alimenta o grupo, o grupo alimenta a linha, a linha alimenta o campo.', 'admin', '/v1/form-constructor', '/api/v1/form-manager/create', 'POST', 'active', 1, '2026-09-20 19:39:28', '2026-09-20 19:39:28', NULL),
	(2, 'usuario-autenticacao', 'user_manager', 'Usuário (Autenticação)', 'Tela de Login do Usuário', NULL, '/v1/user-auth', '/api/v1/auth', 'POST', 'draft', 1, '2026-09-20 19:43:53', '2026-09-20 19:43:53', NULL),
	(3, 'cadastro-usuario', 'user_manager', 'Usuário (Segurança)', 'Primeira etapa de cadastro de usuários.', '["guest","user","admin"]', '/v1/user-manager/create', '/api/v1/user-manager/create', 'POST', 'active', 1, '2026-09-20 19:53:16', '2026-09-20 19:53:16', NULL),
	(4, 'dados-do-usuario', 'user_profiles', 'Usuário (Dados)', 'Cadastro da segunda etapa do Formulário', '["guest","user","admin"]', '/v1/user-manager/create', '/api/v1/user-profiles/create', 'POST', 'active', 1, '2026-09-20 19:53:17', '2026-09-20 19:53:17', NULL),
	(6, 'list-constructor', 'list_manager', 'Construtor de Listagens', 'Meta-formulário: cada grupo abaixo define os campos de uma das três tabelas do módulo List. Preencha de cima para baixo — o formulário alimenta a listagem, a listagem alimenta as colunas e as ações.', 'admin', '/v1/list-constructor', '/api/v1/list-manager/create', 'POST', 'active', 1, '2026-09-20 20:10:04', '2026-09-20 20:10:04', NULL),
	(7, 'cadastro-nav', 'nav_manager', 'Nav (Casca do App)', 'Cadastro da casca de navegação: nome, imagem, ícone de mensagens e versão do sistema exibidos na navbar.', '["admin"]', '/v1/nav-manager/create', '/api/v1/nav-manager/create', 'POST', 'active', 1, '2026-09-20 20:16:32', '2026-09-20 20:16:32', NULL),
	(8, 'cadastro-menu', 'menu_manager', 'Item de Menu', 'Cadastro de item de navegação — pertence a um Nav e pode ter um item pai (submenu).', '["admin"]', '/v1/menu-manager/create', '/api/v1/menu-manager/create', 'POST', 'active', 1, '2026-09-20 20:23:22', '2026-09-20 20:23:22', NULL),
	(9, 'atualizar-upload', 'uploads', 'Upload (Metadados)', 'Edição dos metadados de um arquivo já enviado — título, descrição, categoria e status. Não cria upload novo (isso é feito pelo envio multipart, fora do módulo Form).', '["admin"]', '/v1/upload-manager/update', '/api/v1/upload-manager/update', 'PUT', 'active', 1, '2026-09-20 20:29:27', '2026-09-20 20:29:27', NULL),
	(10, 'cadastro-route', 'route_manager', 'Rota', 'Cadastro manual de uma rota — uso: registrar rota externa que a introspecção automática de Config/Routes.php não captura.', '["admin"]', '/v1/route-manager/create', '/api/v1/route-manager/create', 'POST', 'active', 1, '2026-09-20 20:37:33', '2026-09-20 20:37:33', NULL),
	(11, 'cadastro-role', 'user_roles', 'Perfil de Acesso', 'Cadastro de perfil de acesso (role) — nome, slug, descrição e permissões.', '["admin"]', '/v1/user-roles/create', '/api/v1/user-roles/create', 'POST', 'active', 1, '2026-09-20 20:48:35', '2026-09-20 20:48:35', NULL),
	(12, 'calendario', 'calendar_manager', 'Calendário', 'Cadastro de Calendário', '["guest","user","admin"]', '/v1/calendar-manager/create', '/api/v1/calendar-manager/create', 'POST', 'active', 1, '2026-09-20 21:05:10', '2026-09-20 21:05:10', NULL),
	(13, 'cadastro-evento', 'calendar_events', 'Evento', 'Cadastro de evento dentro de um calendário.', '["guest","user","admin"]', '/v1/calendar-events/create', '/api/v1/calendar-events/create', 'POST', 'active', 1, '2026-09-20 21:05:10', '2026-09-20 21:05:10', NULL),
	(14, 'cadastro-convidado', 'calendar_event_attendees', 'Convidado', 'Cadastro de convidado de um evento de calendário.', '["guest","user","admin"]', '/v1/calendar-event-attendees/create', '/api/v1/calendar-event-attendees/create', 'POST', 'active', 1, '2026-09-20 21:05:10', '2026-09-20 21:05:10', NULL),
	(15, 'cadastro-lembrete', 'calendar_event_reminders', 'Lembrete', 'Cadastro de lembrete de um evento de calendário.', '["guest","user","admin"]', '/v1/calendar-event-reminders/create', '/api/v1/calendar-event-reminders/create', 'POST', 'active', 1, '2026-09-20 21:05:10', '2026-09-20 21:05:10', NULL),
	(16, 'cadastro-anexo-evento', 'calendar_event_attachments', 'Anexo de Evento', 'Cadastro de anexo (por link) de um evento de calendário.', '["guest","user","admin"]', '/v1/calendar-event-attachments/create', '/api/v1/calendar-event-attachments/create', 'POST', 'active', 1, '2026-09-20 21:05:10', '2026-09-20 21:05:10', NULL),
	(17, 'cadastro-propriedade-evento', 'calendar_event_extended_properties', 'Propriedade Estendida', 'Cadastro de propriedade estendida (chave/valor livre) de um evento de calendário.', '["guest","user","admin"]', '/v1/calendar-event-extended-properties/create', '/api/v1/calendar-event-extended-properties/create', 'POST', 'active', 1, '2026-09-20 21:05:10', '2026-09-20 21:05:10', NULL),
	(18, 'editar-calendario', 'calendar_manager', 'Editar Calendário', 'Edição de Calendário', '["guest", "user", "admin"]', '/v1/calendar-manager/:id/update', '/api/v1/calendar-manager/update/{id}', 'PUT', 'active', 1, '2026-09-22 23:49:43', '2026-09-22 23:50:06', NULL),
	(19, 'atualizar-usuario', 'user_profiles', 'Usuário (Atualização)', 'Atualização dos dados do usuário (user_profiles) — mesma base do formulário dados-do-usuario.', '["guest","user","admin"]', '/v1/user-manager/update', '/api/v1/user-profiles/update', 'PUT', 'active', 1, '2026-09-24 16:22:12', '2026-09-24 16:22:12', NULL);

