	(16, 'calendar-manager', 'calendar_manager', 'Calendários — Ações', 'Só guarda as ações por linha (list_actions) da tela /v1/calendar-manager. A grade em si não usa este motor (cards agrupados por view_calendar_manager, não colunas flat) — sem api_get_endpoint de propósito.', NULL, NULL, '["guest", "user", "admin"]', 'id', 'desc', 20, NULL, 'active', 1, '2026-09-23 00:00:42', '2026-09-23 00:00:48', NULL),
	(17, 'calendar-events-view', '', 'Eventos do Calendário', 'Colunas da tabela exibida no modal "Ver eventos" de /v1/calendar-manager. Dado vem do cliente (eventos já carregados da view_calendar_manager, agrupados por calendário) — sem api_get_endpoint de propósito, esta lista não busca nada sozinha.', NULL, NULL, '["guest", "user", "admin"]', 'id', 'desc', 20, NULL, 'active', 1, '2026-09-23 00:01:48', '2026-09-23 00:01:53', NULL),
